If the scene doesn't change every frame (static showroom, paused state), don't render every frame.
let needsRender = true;
controls.addEventListener('change', () => { needsRender = true; });
renderer.setAnimationLoop(() => {
if (needsRender) {
renderer.render(scene, camera);
needsRender = false;
}
});
