Detect FPS over a window; downgrade quality automatically when it drops.
let avgFps = 60;
let quality = 1.0; // 0..1 multiplier
renderer.setAnimationLoop(() => {
const dt = clock.getDelta();
avgFps = avgFps * 0.95 + (1 / dt) * 0.05;
if (avgFps < 40 && quality > 0.5) {
quality -= 0.05;
renderer.setPixelRatio(window.devicePixelRatio * quality);
composer.setSize(innerWidth * quality, innerHeight * quality);
} else if (avgFps > 55 && quality < 1.0) {
quality += 0.02;
renderer.setPixelRatio(window.devicePixelRatio * quality);
}
renderer.render(scene, camera);
});
